Here's a sample C++ program that reads a text file line by line and counts the number of occurrences of a specific word in the file:

```c++
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    string filename, word;
    int count = 0;

    // Prompt user for input file name and word to search
    cout << "Enter input file name: ";
    cin >> filename;

    cout << "Enter word to search: ";
    cin >> word;

    // Open input file for reading
    ifstream infile(filename);

    if (!infile.is_open()) {
        cerr << "Error: Unable to open file " << filename << endl;
        return 1;
    }

    // Read file line by line and count occurrences of word
    string line;
    while (getline(infile, line)) {
        // Convert line to lowercase to ignore case sensitivity
        transform(line.begin(), line.end(), line.begin(), ::tolower);

        // Count occurrences of word in line
        size_t pos = 0;
        while ((pos = line.find(word, pos)) != string::npos) {
            count++;
            pos += word.length();
        }
    }

    // Close input file
    infile.close();

    // Display word count
    cout << "Number of occurrences of \"" << word << "\" in " << filename << ": " << count << endl;

    return 0;
}
```

